'use strict';
(()=>{
const option=(label,hint,effect,success,risk=0)=>({label,hint,effect,success,risk});
const event=(id,title,text,min,max,choices,extra={})=>EVENTS.push({id:'opportunity-'+id,title,text,min,max,choices,lifeOpportunity:true,...extra});
event('education','ทางเรียนที่เหมาะกับบ้าน','ครูใน{place}ให้คุณลองดูตารางเรียน ค่าอุปกรณ์ และเวลาเดินทาง บ้านของ{relative}ยังมีงานที่ต้องแบ่งแรงกัน',10,19,[option('เรียนกับชุมชนต่อ','ปัญญา +7 · โรงเรียนชุมชน',{wisdom:7,education:'community'},'คุณจัดเวลาเรียนกับช่วยงานในบ้าน และได้เพื่อนที่ช่วยกันทบทวน'),option('สมัครฝึกช่าง','พละกำลัง +5 · เริ่มพื้นฐานช่าง',{power:5,wisdom:3,education:'apprentice'},'ช่วงแรกคุณคัดเครื่องมือและทำความสะอาด ก่อนครูช่างให้ลองงานชิ้นเล็ก'),option('สอบทุนเข้าสถาบัน','ปัญญา +9 · มีโอกาสได้ทุน',{wisdom:9,magic:4,education:'academy'},'สถาบันรับคุณพร้อมทุนอุปกรณ์ คุณยังต้องรักษาผลงานในแต่ละภาค',.18),option('เรียนด้วยตนเองหลังช่วยบ้าน','ความสัมพันธ์ +5 · เรียนด้วยตนเอง',{bond:5,wisdom:4,education:'self'},'คุณยืมตำราจากคนรู้จักและจดคำถามไปถามในวันที่ตลาดหยุด')]);
event('first-employer','นายจ้างถามถึงสิ่งที่ทำได้จริง','ผู้ดูแลงานใน{place}ไม่ถามเพียงชื่อสกุล เขาขอดูว่าคุณรับผิดชอบงานหนึ่งชิ้นจนจบได้หรือไม่',16,25,[option('ทดลองงานและขอให้สอนจุดที่ผิด','ปัญญา +6 · พละกำลัง +4',{wisdom:6,power:4},'คุณได้ใบรับรองงานทดลอง ถึงยังไม่ใช่ผู้ชำนาญ แต่มีคนยืนยันความตั้งใจของคุณ'),option('ลองงานรับจ้างหลายแบบก่อน','เหรียญ +10 · ความสุข +3',{gold:10,joy:3},'คุณพบทั้งงานที่ถนัดและงานที่ไม่อยากทำต่อ จึงเลือกเส้นทางได้ชัดขึ้น'),option('เก็บเวลาไว้ฝึกวิชาต่อ','เวท +8',{magic:8,wisdom:3},'คุณจัดตารางฝึกจริงจัง และกลับมาสมัครเมื่อมีชิ้นงานให้ดู')]);
event('coworker','งานที่ค้างอยู่ปลายกะ','เพื่อนร่วมงานขอให้ช่วยปิดงาน แต่คุณมีนัดกับคนในบ้าน งานของ{job}ต้องส่งตรงเวลาและมีคนรับผิดชอบชัดเจน',18,64,[option('แบ่งงานใหม่และบอกเวลาที่ช่วยได้','ความสัมพันธ์ +7',{bond:7,wisdom:3},'คุณช่วยเฉพาะส่วนที่ทำทัน ส่วนที่เหลือส่งต่อพร้อมบันทึก ไม่ปล่อยให้ใครต้องเดา'),option('ทำต่อจนจบแล้วขอวันชดเชย','เหรียญ +12 · สุขภาพ −3',{gold:12,health:-3},'งานเสร็จและนายจ้างลงวันหยุดชดเชยไว้ คุณกลับบ้านช้ากว่าที่บอก'),option('รักษานัดและช่วยเตรียมงานพรุ่งนี้','ความสุข +5',{joy:5,bond:3},'คุณบอกข้อจำกัดตามตรง และจัดรายการของค้างก่อนกลับ')],{needsJob:true});
event('safety','ความเร็วกับความปลอดภัย','งาน{job}ช่วงนี้เร่งขึ้น มีคนเสนอให้ข้ามขั้นตรวจที่ปกติใช้เวลาไม่นาน',18,64,[option('ขอตรวจตามขั้นตอน','ปัญญา +7 · ชื่อเสียง +3',{wisdom:7,fame:3},'คุณพบจุดที่ควรแก้ก่อนส่ง งานช้าลงแต่ไม่ต้องเรียกคืน'),option('ช่วยออกแบบวิธีตรวจให้เร็วขึ้น','ปัญญา +9 · เสี่ยงเล็กน้อย',{wisdom:9,fame:4},'ขั้นตอนใหม่ลดงานซ้ำโดยไม่ตัดการตรวจ',.1),option('รับงานเฉพาะเท่าที่ทำได้','สุขภาพ +6',{health:6,joy:2},'คุณปฏิเสธยอดงานส่วนเกินและรักษาคุณภาพของงานที่รับไว้')],{needsJob:true});
event('retrain','วิชาเดิมเริ่มมีเครื่องมือใหม่','เครื่องมือรุ่นใหม่มาถึง{kingdom} บางคนใช้เวทช่วย บางคนยังเลือกทักษะมือ คุณต้องคิดว่าจะลงทุนฝึกอะไรต่อ',25,60,[option('ลงเรียนหลังเลิกงาน','เหรียญ −12 · ปัญญา +10',{gold:-12,wisdom:10},'คุณกลับมาเป็นผู้เริ่มต้นบางเรื่อง และพบว่าความรู้เก่าช่วยตั้งคำถามได้ดี'),option('แลกวิชากับช่างอีกรุ่น','ความสัมพันธ์ +8 · เวท +5',{bond:8,magic:5},'ต่างคนสอนสิ่งที่ถนัด จนได้วิธีที่เหมาะกับงานของทั้งคู่'),option('พัฒนางานเฉพาะทางที่คนยังต้องใช้','ชื่อเสียง +5 · พละกำลัง +4',{fame:5,power:4},'คุณรับงานที่ต้องใช้ความละเอียดและทำรายการลูกค้าที่กลับมาใช้บริการ')],{needsJob:true});
event('enterprise','แผงว่างในย่านตลาด','ผู้ดูแลตลาดบอกว่ามีพื้นที่ให้เช่า คุณจดค่าอุปกรณ์ ค่าเสบียง และเงินสำรอง แล้วพบว่ารายรับทั้งหมดไม่ใช่กำไร',18,62,[option('ทำบัญชีและลองขายจำนวนน้อย','ปัญญา +8',{wisdom:8,gold:4},'คุณทดสอบตลาดด้วยของจำนวนน้อย ก่อนตัดสินใจเรื่องกิจการจากเมนูอาชีพและกิจการ'),option('ช่วยร้านอื่นเพื่อเรียนงานก่อน','ความสัมพันธ์ +6 · เหรียญ +8',{bond:6,gold:8},'คุณได้เห็นทั้งช่วงขายดีและวันที่ต้องเก็บของเหลือ'),option('เก็บเงินสำรองและทำงานเดิม','ความสุข +5 · เหรียญ +5',{joy:5,gold:5},'คุณยังไม่เช่าพื้นที่ การรอให้พร้อมช่วยให้ไม่มีหนี้ที่ไม่จำเป็น')]);
event('customer','คำร้องเรียนจากลูกค้าที่กลับมา','ลูกค้าประจำของกิจการคุณนำสินค้ากลับมาที่{place} เขาอยากได้คำอธิบายก่อนค่าชดเชย',20,70,[option('รับผิดชอบและแก้ปัญหาให้','เหรียญ −10 · ชื่อเสียง +7',{gold:-10,fame:7,bond:3},'คุณตรวจต้นเหตุและบันทึกวิธีแก้ ลูกค้ายอมให้เวลาอีกครั้ง'),option('ตรวจร่วมกันและปรับขั้นตอน','ปัญญา +8',{wisdom:8,fame:3},'คุณพบว่าปัญหาเกิดระหว่างขนส่ง จึงเปลี่ยนวิธีห่อและเวลารับของ'),option('คืนเงินและอธิบายขอบเขตบริการ','เหรียญ −6 · ความสุข +3',{gold:-6,joy:3},'คุณคืนเงินส่วนที่เหมาะสมและเขียนเงื่อนไขให้คนต่อไปอ่านชัด')],{needsBusiness:true});
event('supplier','ของเข้าร้านช้ากว่ากำหนด','เส้นทางขนส่งใน{kingdom}เสียหาย วัตถุดิบของกิจการคุณมาถึงไม่ครบ คนส่งของนำหลักฐานมาให้ดู',20,70,[option('ลดจำนวนรับงานและแจ้งลูกค้า','ชื่อเสียง +4 · เหรียญ −5',{fame:4,gold:-5},'ยอดขายลดลงในช่วงนี้ แต่ไม่มีงานที่รับปากเกินกำลัง'),option('ช่วยร้านข้างเคียงรวมคำสั่งซื้อ','ความสัมพันธ์ +7 · ปัญญา +4',{bond:7,wisdom:4},'หลายร้านแบ่งค่าขนส่งและตรวจของร่วมกัน'),option('จ่ายส่วนต่างเพื่อใช้แหล่งสำรอง','เหรียญ −15 · ชื่อเสียง +6',{gold:-15,fame:6},'คุณส่งมอบได้ตามนัด และจดต้นทุนที่สูงขึ้นไว้ก่อนรับงานใหม่')],{needsBusiness:true});
event('care','เวลาสำหรับคนในบ้าน','{relative}บอกว่างานในบ้านช่วงนี้หนักกว่าที่คุณเห็น การแบ่งหน้าที่เดิมอาจไม่เหมาะกับอายุและแรงที่เหลือ',28,75,[option('คุยและแบ่งหน้าที่กันใหม่','ความสัมพันธ์ +10',{bond:10,kinTrust:7},'คุณรับส่วนที่ทำได้จริงและนัดกลับมาดูอีกครั้งว่าทุกคนไหวหรือไม่'),option('จ้างคนช่วยงานเป็นช่วง','เหรียญ −12 · สุขภาพ +6',{gold:-12,health:6,bond:4},'เวลาที่คืนมาใช้พักและอยู่ด้วยกัน คนช่วยงานได้รับค่าจ้างตามที่ตกลง'),option('ลดภาระที่ไม่จำเป็นก่อน','ความสุข +7 · ปัญญา +4',{joy:7,wisdom:4},'คุณหยุดทำบางเรื่องที่เคยทำเพราะความเคยชิน และเก็บแรงไว้กับสิ่งสำคัญ')],{needsLivingRelative:true});
event('mentor','คนรุ่นใหม่ขอให้คุณสอน','ผู้เริ่มงานใน{place}ทำพลาดในจุดที่คุณเคยพลาด เขาขอเวลาคุณสั้น ๆ หลังจบวัน',40,84,[option('สอนพร้อมให้เขาลองทำเอง','ความสัมพันธ์ +8 · ชื่อเสียง +6',{bond:8,fame:6},'คุณถอยออกมาดูและให้เขาแก้ด้วยตนเอง เขาเริ่มเข้าใจมากกว่าจำขั้นตอน'),option('เขียนคู่มือจากความผิดพลาดของตน','ปัญญา +8 · ชื่อเสียง +4',{wisdom:8,fame:4},'คู่มือมีทั้งสิ่งที่ควรทำและเหตุผลที่เคยทำอีกแบบแล้วไม่ได้ผล'),option('นัดสอนเป็นเวลาไม่ให้เกินแรง','สุขภาพ +4 · ความสัมพันธ์ +5',{health:4,bond:5},'คุณสอนได้ต่อเนื่องโดยยังมีเวลาพักของตน')],{needsJob:true});
event('later-life','งานที่อยากทำในจังหวะใหม่','คุณทบทวนรายรับ งาน และเวลาที่อยากใช้กับคนใกล้ตัว การทำงานต่อกับการพักไม่จำเป็นต้องมีคำตอบเดียว',62,95,[option('รับงานให้น้อยลงและเลือกมากขึ้น','ทำงาน 60% · ค่าจ้างลดลง · สุขภาพ +8',{health:8,joy:6,workload:.6},'คุณกันวันพักไว้ก่อนรับงาน และบอกคนที่มาติดต่ออย่างชัดเจน'),option('สอนงานแทนการออกแรงทั้งหมด','ทำงาน 80% · ความสัมพันธ์ +9',{bond:9,wisdom:4,workload:.8},'คุณวางเก้าอี้ข้างโต๊ะงาน ให้คำแนะนำในส่วนที่ถ่ายทอดได้'),option('เก็บบันทึกชีวิตให้คนที่อยากอ่าน','ชื่อเสียง +6 · ความสุข +7',{fame:6,joy:7},'คุณเริ่มจากชื่อคนและสถานที่ที่เคยช่วยให้ผ่านวันยาก ๆ มาได้')]);
})();
